mapper.select:
SELECT FROM items
AND ( LOWER(title) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR LOWER(description) LIKE CONCAT('%', LOWER(#{keyword}), '%') OR LOWER(trade_location) LIKE CONCAT('%', LOWER(#{keyword}), '%') )
AND category = #{category}
AND status = #{status}
ORDER BY CASE status WHEN '在售' THEN 0 WHEN '已预订' THEN 1 ELSE 2 END, publish_time DESC

